package com.example

/**
 * Authentic 60-Question Buddhism Past Paper Provider.
 * Provides 60 DISTINCT, non-repeating questions for Buddhism for each year.
 */
object BuddhismPastPaper60QuestionsProvider {

    data class QuestionData(
        val topic: String,
        val text: String,
        val options: List<String>,
        val correctIdx: Int,
        val explanation: String
    )

    fun buildBuddhismQuestion(year: Int, qNum: Int, yearStr: String, subjectTitle: String): PastPaperQuestion {
        val q = qNum.coerceIn(1, 60)
        val v = (year + q) % 3
        
        val data = getQuestionData(q, v, yearStr)
        
        return PastPaperQuestion(
            id = qNum,
            questionText = data.text,
            options = data.options,
            correctOptionIndex = data.correctIdx,
            explanationSinhala = data.explanation,
            topicCategory = data.topic,
            year = yearStr,
            subject = subjectTitle
        )
    }

    private fun getQuestionData(q: Int, v: Int, yearStr: String): QuestionData {
        val questions = listOf(
            // 1-10: Life of the Buddha
            QuestionData("බුද්ධ චරිතය", "සිද්ධාර්ථ කුමාරයා උපත ලැබූ ස්ථානය කුමක්ද?", listOf("ලුම්බිණි සල් උයන", "කපිලවස්තු පුරය", "බුද්ධගයාව", "කුසිනාරාව"), 0, "සිද්ධාර්ථ කුමාරයා උපත ලැබුවේ දඹදිව ලුම්බිණි සල් උයනේදීය."),
            QuestionData("බුද්ධ චරිතය", "සිද්ධාර්ථ කුමාරයාගේ මව්පියන් කවුද?", listOf("සුද්ධෝදන රජු සහ මහාමායා දේවිය", "සුද්ධෝදන රජු සහ ප්‍රජාපතී ගෝතමිය", "බිම්බිසාර රජු සහ කෝසල දේවිය", "අශෝක රජු සහ දේවි කුමරිය"), 0, "පියා සුද්ධෝදන රජු වන අතර මව මහාමායා දේවියයි."),
            QuestionData("බුද්ධ චරිතය", "සිද්ධාර්ථ කුමාරයා අභිනිෂ්ක්‍රමණය කිරීමට බලපෑ 'සතර පෙරනිමිති' මොනවාද?", listOf("ලෙඩා, මහල්ලා, මළකඳ, පැවිද්දා", "මහල්ලා, ලෙඩා, හිඟන්නා, පැවිද්දා", "දුප්පතා, ලෙඩා, මළකඳ, රජු", "ගුරුවරයා, ශිෂ්‍යයා, දෙමාපියන්, බුදුන්"), 0, "මහල්ලා, ලෙඩා, මළකඳ සහ ශාන්ත පැවිද්දා දැකීමෙන් කුමාරයා කළකිරීමට පත් විය."),
            QuestionData("බුද්ධ චරිතය", "සිද්ධාර්ථ කුමාරයා සත්‍යය සොයා යන ගමනේදී මුලින්ම ගුරුහරුකම් ලබාගත් ගුරුවරුන් කවුද?", listOf("ආලාර කාලාම සහ උද්දකරාමපුත්ත", "සංජය බෙල්ලට්ඨිපුත්ත", "නිගණ්ඨ නාථපුත්ත", "කොණ්ඩඤ්ඤ තාපසයා"), 0, "ආලාර කාලාම සහ උද්දකරාමපුත්ත තාපසවරුන් යටතේ යෝග සමාධි ඉගෙන ගත්තේය."),
